import { alt, contentType, generateImageMetadata, runtime, size } from "./opengraph-image.tsx"
import { fillMetadataSegment } from 'next/dist/lib/metadata/get-metadata-route'

const imageModule = { alt, contentType, generateImageMetadata, runtime, size }

export default async function (props) {
    const { __metadata_id__: _, ...params } = await props.params
    const imageUrl = fillMetadataSegment("/p/[rubro]", params, "opengraph-image", false)

    const { generateImageMetadata } = imageModule

    function getImageMetadata(imageMetadata, idParam) {
        const data = {
            alt: imageMetadata.alt,
            type: imageMetadata.contentType || 'image/png',
            url: imageUrl + (idParam ? ('/' + idParam) : '') + '?' + "9ea34a84dc1394f1",
        }
        const { size } = imageMetadata
        if (size) {
            data.width = size.width; data.height = size.height;
        }
        return data
    }

    const imageMetadataArray = await generateImageMetadata({ params })
    return imageMetadataArray.map((imageMetadata, index) => {
        const idParam = imageMetadata.id + ''
        return getImageMetadata(imageMetadata, idParam)
    })
}
